Looking at the examples, I notice that each shape made of 5s is decomposed into:
- **2×2 blocks** colored **8**
- **Thin connectors** (width 1) colored **2**

The key constraint is that uncovered cells (connectors) must never be isolated—each must be adjacent to another uncovered cell. Among valid tilings, we maximize blocks covered, then minimize the number of uncovered connected components.

I verify this against all examples:
- Example 1: 3 non-overlapping 2×2 blocks, connectors form 3 linear paths
- Example 2: 3 blocks with linear column connectors  
- Example 3: 2 blocks with two linear connectors

The algorithm searches over all possible non-overlapping 2×2 block placements and selects the tiling satisfying these criteria.

```python
def solve(grid):
    rows = len(grid)
    cols = len(grid[0])
    fives = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 5:
                fives.add((r, c))
    if not fives:
        return [row[:] for row in grid]
    blocks = []
    for r in range(rows - 1):
        for c in range(cols - 1):
            cells = frozenset([(r, c), (r+1, c), (r, c+1), (r+1, c+1)])
            if cells <= fives:
                blocks.append(cells)
    n = len(blocks)
    def evaluate(covered):
        uncovered = fives - covered
        if not uncovered:
            return (True, len(covered), 0)
        comps = 0; isolated = 0; visited = set()
        for cell in uncovered:
            if cell in visited: continue
            comps += 1; stack = [cell]; visited.add(cell); size = 0
            while stack:
                r, c = stack.pop(); size += 1
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nb = (r+dr, c+dc)
                    if nb in uncovered and nb not in visited:
                        visited.add(nb); stack.append(nb)
            if size == 1: isolated += 1
        return (isolated == 0, len(covered), -comps)
    best_score = None; best_covered = frozenset()
    def search(idx, used, count):
        nonlocal best_score, best_covered
        score = evaluate(used)
        if best_score is None or score > best_score:
            best_score = score; best_covered = frozenset(used)
        if best_score and best_score[0]:
            remaining = n - idx
            if (count + remaining) * 4 <= best_score[1]:
                return
        for i in range(idx, n):
            if not (blocks[i] & used):
                search(i + 1, used | blocks[i], count + 1)
    search(0, frozenset(), 0)
    out = [row[:] for row in grid]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 5:
                out[r][c] = 8 if (r, c) in best_covered else 2
    return out
